//! B3 oracle test: mathd's evaluator against the SymPy/mpmath fixtures
//! (`mathd/fixtures/eval.json`, generated by `mathd/fixtures/generate.py`).
//!
//! Left side of every comparison: this crate's `eval_at`.
//! Right side: the committed expected value, computed by mpmath at 30+
//! digits through SymPy. The two share no code (AGENTS.md rule 1).
//!
//! The JSON is read by a minimal reader written for exactly this file's
//! shape (objects, arrays, strings, finite numbers, no nesting beyond what
//! the generator emits). It is deliberately small and test-covered below;
//! anything it cannot understand is a hard error, never a silent skip.
//!
//! Tolerances: relative 1e-10 for all nonzero values, and exact zero (0.0)
//! for zero expected values. Constant inputs like sin(pi) and tan(pi) in f64
//! evaluate using f64::consts::PI and match the oracle evaluated at
//! float(math.pi) within the relative gate.

use mathd::{eval_at, parse, EvalError};
use std::collections::HashMap;
use std::fs;

// ---------------------------------------------------------------- JSON

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        match self {
            Json::Obj(pairs) => pairs.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
    fn as_str(&self) -> Option<&str> {
        match self {
            Json::Str(s) => Some(s),
            _ => None,
        }
    }
    fn as_f64(&self) -> Option<f64> {
        match self {
            Json::Num(v) => Some(*v),
            _ => None,
        }
    }
    fn as_arr(&self) -> Option<&[Json]> {
        match self {
            Json::Arr(v) => Some(v),
            _ => None,
        }
    }
}

struct P<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> P<'a> {
    fn ws(&mut self) {
        while self.i < self.b.len() && (self.b[self.i] as char).is_ascii_whitespace() {
            self.i += 1;
        }
    }
    fn peek(&self) -> Option<u8> {
        self.b.get(self.i).copied()
    }
    fn expect(&mut self, c: u8) -> Result<(), String> {
        if self.peek() == Some(c) {
            self.i += 1;
            Ok(())
        } else {
            Err(format!(
                "expected '{}' at byte {}, found {:?}",
                c as char,
                self.i,
                self.peek().map(|x| x as char)
            ))
        }
    }
    fn value(&mut self) -> Result<Json, String> {
        self.ws();
        match self.peek() {
            Some(b'{') => self.object(),
            Some(b'[') => self.array(),
            Some(b'"') => self.string().map(Json::Str),
            Some(b't') => self.lit("true").map(|_| Json::Bool(true)),
            Some(b'f') => self.lit("false").map(|_| Json::Bool(false)),
            Some(b'n') => self.lit("null").map(|_| Json::Null),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.number(),
            other => Err(format!(
                "unexpected {:?} at byte {}",
                other.map(|x| x as char),
                self.i
            )),
        }
    }
    fn lit(&mut self, s: &str) -> Result<(), String> {
        if self.b[self.i..].starts_with(s.as_bytes()) {
            self.i += s.len();
            Ok(())
        } else {
            Err(format!("expected {} at byte {}", s, self.i))
        }
    }
    fn number(&mut self) -> Result<Json, String> {
        let start = self.i;
        if self.peek() == Some(b'-') {
            self.i += 1;
        }
        while self
            .peek()
            .map(|c| c.is_ascii_digit() || matches!(c, b'.' | b'e' | b'E' | b'+' | b'-'))
            .unwrap_or(false)
        {
            self.i += 1;
        }
        let text = std::str::from_utf8(&self.b[start..self.i]).map_err(|e| e.to_string())?;
        text.parse::<f64>()
            .map(Json::Num)
            .map_err(|e| format!("bad number {:?}: {}", text, e))
    }
    fn string(&mut self) -> Result<String, String> {
        self.expect(b'"')?;
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Err("unterminated string".to_string()),
                Some(b'"') => {
                    self.i += 1;
                    return Ok(out);
                }
                Some(b'\\') => {
                    self.i += 1;
                    match self.peek() {
                        Some(b'"') => out.push('"'),
                        Some(b'\\') => out.push('\\'),
                        Some(b'/') => out.push('/'),
                        Some(b'n') => out.push('\n'),
                        Some(b't') => out.push('\t'),
                        Some(b'r') => out.push('\r'),
                        Some(b'u') => {
                            if self.i + 4 >= self.b.len() {
                                return Err("bad \\u escape".to_string());
                            }
                            let hex = std::str::from_utf8(&self.b[self.i + 1..self.i + 5])
                                .map_err(|e| e.to_string())?;
                            let cp = u32::from_str_radix(hex, 16).map_err(|e| e.to_string())?;
                            out.push(char::from_u32(cp).ok_or("bad codepoint")?);
                            self.i += 4;
                        }
                        other => return Err(format!("bad escape {:?}", other.map(|x| x as char))),
                    }
                    self.i += 1;
                }
                Some(_) => {
                    // Copy one UTF-8 character.
                    let s = std::str::from_utf8(&self.b[self.i..]).map_err(|e| e.to_string())?;
                    let ch = s.chars().next().unwrap();
                    out.push(ch);
                    self.i += ch.len_utf8();
                }
            }
        }
    }
    fn array(&mut self) -> Result<Json, String> {
        self.expect(b'[')?;
        let mut items = Vec::new();
        self.ws();
        if self.peek() == Some(b']') {
            self.i += 1;
            return Ok(Json::Arr(items));
        }
        loop {
            items.push(self.value()?);
            self.ws();
            match self.peek() {
                Some(b',') => {
                    self.i += 1;
                }
                Some(b']') => {
                    self.i += 1;
                    return Ok(Json::Arr(items));
                }
                other => {
                    return Err(format!(
                        "expected ',' or ']', got {:?}",
                        other.map(|x| x as char)
                    ))
                }
            }
        }
    }
    fn object(&mut self) -> Result<Json, String> {
        self.expect(b'{')?;
        let mut pairs = Vec::new();
        self.ws();
        if self.peek() == Some(b'}') {
            self.i += 1;
            return Ok(Json::Obj(pairs));
        }
        loop {
            self.ws();
            let key = self.string()?;
            self.ws();
            self.expect(b':')?;
            let val = self.value()?;
            pairs.push((key, val));
            self.ws();
            match self.peek() {
                Some(b',') => {
                    self.i += 1;
                }
                Some(b'}') => {
                    self.i += 1;
                    return Ok(Json::Obj(pairs));
                }
                other => {
                    return Err(format!(
                        "expected ',' or '}}', got {:?}",
                        other.map(|x| x as char)
                    ))
                }
            }
        }
    }
}

fn parse_json(text: &str) -> Result<Json, String> {
    let mut p = P {
        b: text.as_bytes(),
        i: 0,
    };
    let v = p.value()?;
    p.ws();
    if p.i != text.len() {
        return Err(format!("trailing bytes at {}", p.i));
    }
    Ok(v)
}

// ---------------------------------------------------------------- harness

struct Case {
    expr: String,
    bindings: HashMap<String, f64>,
    expected: Option<f64>,
    error_kind: Option<String>,
}

const TOLERANCE_RELATIVE: f64 = 1e-10;
const ZERO_TOLERANCE_ABSOLUTE: f64 = 0.0;

fn load_cases() -> Vec<Case> {
    // CARGO_MANIFEST_DIR is mathd/; fixtures live at mathd/fixtures/eval.json.
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/eval.json");
    let text = fs::read_to_string(path).unwrap_or_else(|e| {
        panic!(
            "cannot read {} (run mathd/fixtures/generate.py): {}",
            path, e
        )
    });
    let root = parse_json(&text).expect("eval.json is not valid JSON per the minimal reader");
    let rel_tol = root
        .get("tolerance_relative")
        .and_then(|v| v.as_f64())
        .expect("missing tolerance_relative");
    assert_eq!(
        rel_tol, TOLERANCE_RELATIVE,
        "eval.json header tolerance_relative ({}) != test TOLERANCE_RELATIVE ({})",
        rel_tol, TOLERANCE_RELATIVE
    );
    let zero_tol = root
        .get("zero_tolerance_absolute")
        .and_then(|v| v.as_f64())
        .expect("missing zero_tolerance_absolute");
    assert_eq!(
        zero_tol, ZERO_TOLERANCE_ABSOLUTE,
        "eval.json header zero_tolerance_absolute ({}) != test ZERO_TOLERANCE_ABSOLUTE ({})",
        zero_tol, ZERO_TOLERANCE_ABSOLUTE
    );
    let cases_json = root
        .get("cases")
        .and_then(|v| v.as_arr())
        .expect("missing cases array");
    cases_json
        .iter()
        .map(|c| {
            let expr = c
                .get("expr")
                .and_then(|v| v.as_str())
                .expect("case missing expr")
                .to_string();
            let mut bindings = HashMap::new();
            if let Some(Json::Obj(pairs)) = c.get("bindings") {
                for (k, v) in pairs {
                    bindings.insert(k.clone(), v.as_f64().expect("binding not a number"));
                }
            }
            Case {
                expr,
                bindings,
                expected: c.get("expected").and_then(|v| v.as_f64()),
                error_kind: c
                    .get("error_kind")
                    .and_then(|v| v.as_str())
                    .map(String::from),
            }
        })
        .collect()
}

fn close(got: f64, want: f64) -> bool {
    if want == 0.0 {
        got == 0.0
    } else {
        ((got - want) / want).abs() <= TOLERANCE_RELATIVE
    }
}

fn kind_of(err: &EvalError) -> &'static str {
    match err {
        EvalError::Domain { .. } => "domain",
        EvalError::DivisionByZero { .. } => "division_by_zero",
        EvalError::Overflow => "overflow",
        EvalError::Undefined { .. } => "undefined",
    }
}

// ---------------------------------------------------------------- tests

/// The work-order gate: every valid fixture case agrees within 1e-10
/// relative error; every error case produces the named EvalError kind.
/// No case is skipped — a parse failure here is a test failure.
#[test]
fn evaluator_agrees_with_sympy_fixtures() {
    let cases = load_cases();
    assert!(
        cases.len() >= 2000,
        "fixture set has {} cases, need >= 2000",
        cases.len()
    );
    let n_valid = cases.iter().filter(|c| c.expected.is_some()).count();
    assert!(
        n_valid >= 2000,
        "only {} valid cases (work order demands >= 2000 (expr, bindings, expected) triples)",
        n_valid
    );

    let mut failures: Vec<String> = Vec::new();
    let mut checked = 0usize;
    for c in &cases {
        let ast = match parse(&c.expr) {
            Ok(a) => a,
            Err(e) => {
                failures.push(format!("PARSE {:?}: {}", c.expr, e));
                continue;
            }
        };
        match (eval_at(&ast, &c.bindings), c.expected, &c.error_kind) {
            (Ok(got), Some(want), _) => {
                checked += 1;
                if !close(got, want) {
                    failures.push(format!(
                        "VALUE {:?} bindings={:?}: got {:e}, want {:e} (rel err {:e})",
                        c.expr,
                        c.bindings,
                        got,
                        want,
                        ((got - want) / want).abs()
                    ));
                }
            }
            (Ok(got), None, Some(kind)) => {
                checked += 1;
                failures.push(format!(
                    "SHOULD-ERR {:?}: expected {} error, got value {}",
                    c.expr, kind, got
                ));
            }
            (Ok(_), None, None) => {
                failures.push(format!(
                    "NO-ANNOTATION {:?}: evaluated to a value, but the case has neither expected nor error_kind",
                    c.expr
                ));
            }
            (Err(e), Some(want), _) => {
                checked += 1;
                failures.push(format!(
                    "SHOULD-VALUE {:?} bindings={:?}: got error {}, want {}",
                    c.expr, c.bindings, e, want
                ));
            }
            (Err(e), None, Some(kind)) => {
                checked += 1;
                if kind_of(&e) != kind.as_str() {
                    failures.push(format!(
                        "KIND {:?}: expected {} error, got {} ({})",
                        c.expr,
                        kind,
                        kind_of(&e),
                        e
                    ));
                }
            }
            (Err(e), None, None) => {
                failures.push(format!(
                    "NO-ANNOTATION {:?}: errored ({}), but the case has neither expected nor error_kind",
                    c.expr, e
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} fixture cases failed:\n{}",
        failures.len(),
        checked,
        failures.join("\n")
    );
}

/// The fixture file's own header must describe what it contains — a count
/// that disagrees with the data is exactly the "95 glyphs" class of defect
/// this project was built to prevent (AGENTS.md rule 10).
#[test]
fn fixture_header_counts_match_the_data() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/eval.json");
    let text = fs::read_to_string(path).unwrap();
    let root = parse_json(&text).unwrap();
    let cases = root.get("cases").and_then(|v| v.as_arr()).unwrap();
    let coverage = root.get("function_coverage").unwrap();
    if let Json::Obj(pairs) = coverage {
        for (fname, count) in pairs {
            let claimed = count.as_f64().unwrap() as usize;
            let needle = format!("{}(", fname);
            let actual = cases
                .iter()
                .filter(|c| {
                    c.get("expr")
                        .and_then(|v| v.as_str())
                        .map(|e| e.contains(&needle))
                        .unwrap_or(false)
                })
                .count();
            assert_eq!(
                claimed, actual,
                "function_coverage claims {} cases for {}, data has {}",
                claimed, fname, actual
            );
        }
    }
}

/// The minimal JSON reader itself, against shapes the generator does and
/// does not emit — a reader that cannot fail loudly would silently skip
/// fixture cases.
#[test]
fn json_reader_behaves() {
    use Json::*;
    assert_eq!(parse_json("1.5").unwrap(), Num(1.5));
    assert_eq!(parse_json("-2").unwrap(), Num(-2.0));
    assert_eq!(parse_json("1e3").unwrap(), Num(1000.0));
    assert_eq!(parse_json("\"a\\u00e9b\"").unwrap(), Str("aéb".to_string()));
    match parse_json("[1, \"x\", {\"k\": -0.5}]").unwrap() {
        Arr(v) => {
            assert_eq!(v.len(), 3);
            assert_eq!(v[0], Num(1.0));
            assert_eq!(v[1], Str("x".to_string()));
            match &v[2] {
                Obj(p) => {
                    assert_eq!(p.len(), 1);
                    assert_eq!(p[0].0, "k");
                    assert_eq!(p[0].1, Num(-0.5));
                }
                other => panic!("expected Obj, got {:?}", other),
            }
        }
        other => panic!("expected Arr, got {:?}", other),
    }
    // Malformed input fails loudly, never panics.
    for bad in [
        "",
        "{",
        "[1,",
        "\"unterminated",
        "{\"a\"}",
        "1 2",
        "nul",
        "[1] x",
    ] {
        assert!(parse_json(bad).is_err(), "{:?} should not parse", bad);
    }
}
